param([string]$BaseUrl='http://localhost:18081')
$ErrorActionPreference='Stop'
$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$environmentNames=@('PAYMENT_CANCELLATION_CRASH_LAB_ENABLED','PAYMENT_CANCELLATION_CRASH_LAB_ORDER_ID',
  'PAYMENT_CANCELLATION_CRASH_LAB_PHASE','PAYMENT_CANCELLATION_CRASH_LAB_PAUSE')
$saved=@{};foreach($name in $environmentNames){$saved[$name]=[Environment]::GetEnvironmentVariable($name)}

function Compose([string[]]$Arguments){& docker compose --project-directory $projectRoot @Arguments;if($LASTEXITCODE-ne0){throw "Compose failed: $($Arguments-join' ')"}}
function Sql([string]$Statement){$v=& docker compose --project-directory $projectRoot exec -T commerce-db mysql -ucommerceflow -pcommerceflow-password -Nse $Statement commerceflow 2>$null;if($LASTEXITCODE-ne0){throw 'Storefront SQL failed'};return($v-join"`n").Trim()}
function PaymentSql([string]$Statement){$v=& docker compose --project-directory $projectRoot exec -T payment-simulator-db mysql -upayment -ppayment-password -Nse $Statement payment_platform 2>$null;if($LASTEXITCODE-ne0){throw 'Payment SQL failed'};return($v-join"`n").Trim()}
function Wait-Healthy{for($i=0;$i-lt45;$i++){try{if((Invoke-RestMethod "$BaseUrl/actuator/health").status-eq'UP'){return}}catch{};Start-Sleep 1};throw 'Backend did not become healthy'}
function Restart-Backend([long]$OrderId=1,[string]$Phase='AFTER_CANCELLATION_BEGIN',[bool]$Enabled=$false){$env:PAYMENT_CANCELLATION_CRASH_LAB_ENABLED=$Enabled.ToString().ToLowerInvariant();$env:PAYMENT_CANCELLATION_CRASH_LAB_ORDER_ID=[string]$OrderId;$env:PAYMENT_CANCELLATION_CRASH_LAB_PHASE=$Phase;$env:PAYMENT_CANCELLATION_CRASH_LAB_PAUSE='5m';Compose @('up','-d','--no-deps','--force-recreate','commerce-service');Wait-Healthy}
function New-Session([string]$Email){$s=[Microsoft.PowerShell.Commands.WebRequestSession]::new();$c=Invoke-RestMethod "$BaseUrl/api/auth/csrf" -WebSession $s;$h=@{};$h[$c.headerName]=$c.token;Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -WebSession $s -Headers $h -ContentType application/json -Body (@{email=$Email;password='demo-password';rememberMe=$false}|ConvertTo-Json -Compress)|Out-Null;return @{Session=$s;Headers=$h}}
function Prepare-Customer{$customer=New-Session 'demo@example.com';try{Invoke-RestMethod "$BaseUrl/api/addresses/selected" -WebSession $customer.Session|Out-Null}catch{$a=Invoke-RestMethod "$BaseUrl/api/addresses" -Method Post -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body '{"recipientName":"Crash Lab","phone":"13800000000","countryCode":"CN","stateProvince":"Shanghai","city":"Shanghai","district":"Pudong","addressLine1":"2 Recovery Road","addressLine2":"","postalCode":"200120","label":"Crash Lab","isDefault":true}';Invoke-RestMethod "$BaseUrl/api/addresses/$($a.id)/select" -Method Put -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body '{}'|Out-Null};return $customer}
function New-PendingOrder{$customer=Prepare-Customer;Invoke-RestMethod "$BaseUrl/api/cart/items" -Method Post -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body '{"productId":1,"quantity":1,"note":"crash-recovery-lab"}'|Out-Null;$order=Invoke-RestMethod "$BaseUrl/api/purchase-orders/checkout" -Method Post -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body '{}';$payment=Invoke-RestMethod "$BaseUrl/api/purchase-orders/$($order.id)/payments" -Method Post -WebSession $customer.Session -Headers $customer.Headers -ContentType application/json -Body (@{idempotencyKey=[guid]::NewGuid().ToString();simulateFailure=$false;channel='ALIPAY'}|ConvertTo-Json -Compress);return @{Order=$order;Payment=$payment.payment}}
function Start-Cancel([long]$OrderId){return Start-ThreadJob -ArgumentList $BaseUrl,$OrderId -ScriptBlock {param($Url,$Id);$s=[Microsoft.PowerShell.Commands.WebRequestSession]::new();$c=Invoke-RestMethod "$Url/api/auth/csrf" -WebSession $s;$h=@{};$h[$c.headerName]=$c.token;Invoke-RestMethod "$Url/api/auth/login" -Method Post -WebSession $s -Headers $h -ContentType application/json -Body '{"email":"demo@example.com","password":"demo-password","rememberMe":false}'|Out-Null;try{Invoke-RestMethod "$Url/api/purchase-orders/$Id/cancel" -Method Post -WebSession $s -Headers $h -ContentType application/json -Body '{"reason":"process crash recovery lab"}'|Out-Null}catch{}}}
function Wait-Pause([long]$OrderId,[string]$Phase){for($i=0;$i-lt30;$i++){$logs=& docker compose --project-directory $projectRoot logs --no-color commerce-service 2>$null;if("$logs"-match"PAYMENT_CANCELLATION_CRASH_LAB_PAUSED orderId=$OrderId phase=$Phase"){return};Start-Sleep 1};throw "Crash hook was not reached for order $OrderId phase $Phase"}
function Kill-Backend([System.Management.Automation.Job]$Job){Compose @('kill','-s','SIGKILL','commerce-service');$Job|Remove-Job -Force -ErrorAction SilentlyContinue}
function Retry-Cancel([long]$OrderId){$c=Prepare-Customer;return Invoke-RestMethod "$BaseUrl/api/purchase-orders/$OrderId/cancel" -Method Post -WebSession $c.Session -Headers $c.Headers -ContentType application/json -Body '{"reason":"process crash recovery lab retry"}'}
function Notice($Fixture,[string]$Prefix){$raw=@{notificationId="$Prefix-$([guid]::NewGuid().ToString('N'))";channelTransactionNo=$Fixture.Payment.channelTransactionNo;channel='ALIPAY';status='SUCCESS';amount=$Fixture.Payment.amount;currency='CNY';failureReason=''}|ConvertTo-Json -Compress;$mac=[Security.Cryptography.HMACSHA256]::new([Text.Encoding]::UTF8.GetBytes('demo-platform-callback-secret'));return @{Raw=$raw;Signature=[Convert]::ToBase64String($mac.ComputeHash([Text.Encoding]::UTF8.GetBytes($raw)))}}

try{
  Restart-Backend
  $merchant=New-Session 'merchant@example.com';$product=(Invoke-RestMethod "$BaseUrl/api/merchant/inventory" -WebSession $merchant.Session|Where-Object productId -eq 1|Select-Object -First 1);if([int]$product.stockAvailable-lt20){Invoke-RestMethod "$BaseUrl/api/merchant/inventory/1/adjustments" -Method Post -WebSession $merchant.Session -Headers $merchant.Headers -ContentType application/json -Body (@{delta=20-[int]$product.stockAvailable;reason='Prepare crash recovery lab inventory'}|ConvertTo-Json -Compress)|Out-Null}

  $begin=New-PendingOrder;Restart-Backend $begin.Order.id 'AFTER_CANCELLATION_BEGIN' $true;$job=Start-Cancel $begin.Order.id;Wait-Pause $begin.Order.id 'AFTER_CANCELLATION_BEGIN';Kill-Backend $job
  if((Sql "SELECT CONCAT(o.status,':',p.status) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$($begin.Order.id)")-ne'CANCELLING:PENDING'){throw 'Crash after cancellation begin did not preserve the recoverable middle state'}
  Restart-Backend; if((Retry-Cancel $begin.Order.id).status-ne'CANCELLED'){throw 'CANCELLING retry did not finish cancellation'}

  $closed=New-PendingOrder;Restart-Backend $closed.Order.id 'AFTER_CHANNEL_CLOSE' $true;$job=Start-Cancel $closed.Order.id;Wait-Pause $closed.Order.id 'AFTER_CHANNEL_CLOSE';Kill-Backend $job
  if((Sql "SELECT CONCAT(o.status,':',p.status) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$($closed.Order.id)")-ne'CANCELLING:PENDING'){throw 'Local facts changed before the post-close crash'}
  if((PaymentSql "SELECT status FROM channel_transaction WHERE channel_transaction_no='$($closed.Payment.channelTransactionNo)'")-ne'CLOSED'){throw 'Channel close was not committed before the crash'}
  Restart-Backend;if((Retry-Cancel $closed.Order.id).status-ne'CANCELLED'){throw 'Retry after committed channel close did not finish cancellation'}
  if((Sql "SELECT CONCAT(status,':',(SELECT COUNT(*) FROM order_events WHERE order_id=$($closed.Order.id) AND event_type='ORDER_CANCELLED')) FROM payment_records WHERE order_id=$($closed.Order.id)")-ne'CLOSED:1'){throw 'Post-close retry produced inconsistent or duplicate local facts'}

  $paymentCrash=New-PendingOrder;$notice=Notice $paymentCrash 'CRASH';Restart-Backend $paymentCrash.Order.id 'AFTER_PAYMENT_RECORD' $true
  $job=Start-ThreadJob -ArgumentList $BaseUrl,$notice.Raw,$notice.Signature -ScriptBlock {param($Url,$Raw,$Sig);try{Invoke-RestMethod "$Url/api/payment-notifications/callback" -Method Post -Headers @{'X-Callback-Signature'=$Sig} -ContentType application/json -Body $Raw|Out-Null}catch{}}
  Wait-Pause $paymentCrash.Order.id 'AFTER_PAYMENT_RECORD';Kill-Backend $job
  if((Sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM payment_notifications WHERE payment_id=p.id),':',(SELECT COUNT(*) FROM payment_events WHERE payment_id=p.id AND event_type='CALLBACK_SUCCESS')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$($paymentCrash.Order.id)")-ne'PENDING_PAYMENT:PENDING:0:0'){throw 'Hard crash inside the payment callback transaction was not fully rolled back'}
  Restart-Backend;$result=Invoke-RestMethod "$BaseUrl/api/payment-notifications/callback" -Method Post -Headers @{'X-Callback-Signature'=$notice.Signature} -ContentType application/json -Body $notice.Raw;if($result.result-ne'PROCESSED'){throw 'Payment callback retry failed after transaction rollback'}
  if((Sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM payment_notifications WHERE payment_id=p.id),':',(SELECT COUNT(*) FROM payment_events WHERE payment_id=p.id AND event_type='CALLBACK_SUCCESS')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$($paymentCrash.Order.id)")-ne'PAID:SUCCESS:1:1'){throw 'Payment callback retry did not commit exactly one accounting fact'}

  $late=New-PendingOrder;Restart-Backend $late.Order.id 'AFTER_CANCELLATION_BEGIN' $true;$job=Start-Cancel $late.Order.id;Wait-Pause $late.Order.id 'AFTER_CANCELLATION_BEGIN';Kill-Backend $job;Restart-Backend;$lateNotice=Notice $late 'LATE';$result=Invoke-RestMethod "$BaseUrl/api/payment-notifications/callback" -Method Post -Headers @{'X-Callback-Signature'=$lateNotice.Signature} -ContentType application/json -Body $lateNotice.Raw;if($result.result-ne'PROCESSED'){throw 'Late callback was not processed'}
  if((Sql "SELECT CONCAT(o.status,':',p.status,':',(SELECT COUNT(*) FROM order_events WHERE order_id=o.id AND event_type='CANCELLATION_LOST_PAYMENT_RACE')) FROM shop_orders o JOIN payment_records p ON p.order_id=o.id WHERE o.id=$($late.Order.id)")-ne'PAID:SUCCESS:1'){throw 'Late callback did not recover the payment fact from CANCELLING'}
  Write-Host 'Payment/cancellation crash recovery passed: begin, committed channel close, callback rollback and late callback windows.' -ForegroundColor Green
}finally{foreach($name in $environmentNames){if($null-eq$saved[$name]){Remove-Item "Env:$name" -ErrorAction SilentlyContinue}else{[Environment]::SetEnvironmentVariable($name,$saved[$name])}};try{Compose @('up','-d','--no-deps','--force-recreate','commerce-service');Wait-Healthy}catch{Write-Warning $_}}
